import {useState} from 'react';
import {api} from './api';
import {Field,Form} from './ui';
export default function Security({user,onRefresh}) {
 const [setup,setSetup]=useState(null),[qr,setQr]=useState(''),[notice,setNotice]=useState('');
 return <section className="security"><h1>Protect your workspace.</h1><p className="muted">Use an authenticator app for account protection. Once enabled, eligible members can sign in using an email code and their authenticator instead of a password when email delivery is connected. Administrators keep password and authenticator sign-in.</p><div className="form-panel"><h2>{user.mfaEnabled?'Fresh authentication':'Set up two-factor authentication'}</h2>{user.mfaEnabled?<><p className="muted">Confirm your password and a new authenticator code. Administrative access stays fresh for five minutes.</p><Form submit="Verify identity" onSubmit={async data=>{await api('/auth/reauth','POST',data);setNotice('Identity verified for sensitive actions.');await onRefresh();}}><Field label="Password" name="password" type="password" required autoComplete="current-password"/><Field label="Authenticator code" name="code" required pattern="[0-9]{6}" maxLength={6} inputMode="numeric" autoComplete="one-time-code"/></Form></>:setup?<><p className="muted">Scan this code with your authenticator app. Keep the setup secret private.</p>{qr?<img className="totp-qr" src={qr} alt="Authenticator enrollment QR code"/>:null}<details><summary>Enter setup key manually</summary><code className="secret">{setup.secret}</code></details><Form submit="Enable two-factor authentication" onSubmit={async data=>{await api('/auth/mfa/confirm','POST',data);setSetup(null);setQr('');setNotice('Two-factor authentication is enabled.');await onRefresh();}}><Field label="Authenticator code" name="code" required pattern="[0-9]{6}" maxLength={6} inputMode="numeric"/></Form></>:<Form submit="Set up authenticator" onSubmit={async data=>{const value=await api('/auth/mfa/setup','POST',data);const QRCode=await import('qrcode');setQr(await QRCode.toDataURL(value.uri,{width:220,margin:1}));setSetup(value);}}><Field label="Confirm password" name="password" type="password" required autoComplete="current-password"/></Form>}{notice?<p role="status" className="notice">{notice}</p>:null}</div><p className="small muted">Recovery codes and verified email recovery are not configured. Keep your authenticator available; do not use this development deployment as your only account access.</p></section>;
}
